head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};

scwin.btnPop_onclick = function(e) {
	var options = {
		id: "popup1",
		type: "wframePopup",
		width: "230px",
		height: "250px",
		top: "130px",
		left: "200px",
		popupName: "openPopup1",
		modal: true,
		useModalStack: true,
		alwaysOnTop: false,
		resizable: true,
		status: true,
		menubar: false,
		scrollbars: false,
		title: false,
		closeAction: "scwin.callback"
	};
	scwin.$w.openPopup("/sample/common_link/p_popup_popWin_WEFF-285_(WSQ-3549)_sub.xml", options);
};

scwin.callback = function() {
	var options = {
		id: "popup2",
		type: "wframePopup",
		width: "230px",
		height: "250px",
		top: "130px",
		left: "500px",
		popupName: "openPopup1",
		modal: true,
		useModalStack: true,
		alwaysOnTop: false,
		resizable: true,
		status: true,
		menubar: false,
		scrollbars: false,
		title: false,
		closeAction: "scwin.callback2"
	};
	scwin.$w.openPopup("/sample/common_link/p_popup_popWin_WEFF-285_(WSQ-3549)_sub.xml", options);
	return true;
};

scwin.checkLog = function() {
	return WebSquare.logger.getErrorLog();
};
